mapper.select:
/* LeaveDeductionMapper.selectDailySchedule */ SELECT S.SCH_CD AS schCd , S.FST_SCH_STR_TIME AS fstSchStrTime , S.FST_SCH_END_TIME AS fstSchEndTime , S.FST_SCH_BRK_MIN AS fstSchBrkMin , S.SEC_SCH_STR_TIME AS secSchStrTime , S.SEC_SCH_END_TIME AS secSchEndTime , S.SEC_SCH_BRK_MIN AS secSchBrkMin , S.FST_BRK_STR_TIME AS fstBrkStrTime , S.FST_BRK_END_TIME AS fstBrkEndTime , S.SEC_BRK_STR_TIME AS secBrkStrTime , S.SEC_BRK_END_TIME AS secBrkEndTime FROM TB_USER_WORK_PLAN WP
JOIN ( SELECT E.CMPNY_CD, E.SITE_CD, E.SCH_CD, E.APPLY_DATE , E.FST_SCH_STR_TIME, E.FST_SCH_END_TIME, E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME, E.SEC_SCH_END_TIME, E.SEC_SCH_BRK_MIN , E.FST_BRK_STR_TIME, E.FST_BRK_END_TIME , E.SEC_BRK_STR_TIME, E.SEC_BRK_END_TIME FROM ( SELECT M.CMPNY_CD, M.SITE_CD, M.SCH_CD, M.APPLY_DATE , M.FST_SCH_STR_TIME, M.FST_SCH_END_TIME, M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME, M.SEC_SCH_END_TIME, M.SEC_SCH_BRK_MIN , M.FST_BRK_STR_TIME, M.FST_BRK_END_TIME , M.SEC_BRK_STR_TIME, M.SEC_BRK_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M UNION ALL SELECT H.CMPNY_CD, H.SITE_CD, H.SCH_CD, H.APPLY_DATE , H.FST_SCH_STR_TIME, H.FST_SCH_END_TIME, H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME, H.SEC_SCH_END_TIME, H.SEC_SCH_BRK_MIN , H.FST_BRK_STR_TIME, H.FST_BRK_END_TIME , H.SEC_BRK_STR_TIME, H.SEC_BRK_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) S ON S.CMPNY_CD = WP.CMPNY_CD AND S.SITE_CD = WP.SITE_CD AND S.SCH_CD = WP.WORK_PLAN_CD AND S.APPLY_DATE = (
SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD ) WHERE WP.CMPNY_CD = #{cmpnyCd} AND WP.SITE_CD = #{siteCd} AND WP.USER_CD = #{userCd} AND WP.WORK_YMD = #{workYmd} LIMIT 1

/* LeaveDeductionMapper.selectHourlyLeaveAggOnDate */
SELECT
      IFNULL(SUM(U.LEAVE_MINUTES), 0) AS cumMinutes
    , IFNULL(SUM(U.LEAVE_DAYS), 0)    AS cumChargedDays
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.START_DATE    = #{workYmd}
   AND U.USE_UNIT_TYPE IN ('02', '03', '04')
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
